<?php use App\Support\App;$u=App::requireAuth();$q=App::db()->prepare('SELECT o.*,p.name product_name FROM orders o JOIN products p ON p.id=o.product_id WHERE o.user_id=? ORDER BY o.id DESC LIMIT 200');$q->execute([$u['id']]);$rows=$q->fetchAll();$title='Order History';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">Order history</h1><p class="page-sub">Pantau seluruh order IMEI Anda.</p></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[720px]"><thead><tr><th>Order</th><th>Service</th><th>IMEI</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td class="font-semibold"><?=htmlspecialchars($r['order_number'])?></td><td><?=htmlspecialchars($r['product_name'])?></td><td class="font-mono"><?=htmlspecialchars($r['imei'])?></td><td>Rp<?=number_format($r['selling_price'],0,',','.')?></td><td><span class="badge"><?=htmlspecialchars($r['status'])?></span></td><td class="text-zinc-500"><?=htmlspecialchars($r['created_at'])?></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="p-10 text-center text-zinc-500">Belum ada order.</div><?php endif?></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>